#!/usr/bin/env python3
"""Build the offline CU-inspired deck, preserving report and experiment sources.

Usage: python3 project/tools/build_presentation.py --reference /path/to/reference.html
Only embedded font-face rules and the first CU logo are reused from the supplied
reference. All slide content and controller code belong to this presentation.
"""
import argparse
import hashlib
import html
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EVIDENCE = ROOT / 'evidence'
OUTPUT = ROOT / 'YouAreBot_CU_Presentation.html'


def esc(value):
    return html.escape(str(value), quote=True)


def num(value):
    return f'{value:,}'.replace(',', ' ')


def metric(value):
    return f'{value:.6f}'


def stat(value, label, color=''):
    return f'<div class="stat {color}"><div class="number">{esc(value)}</div><p>{label}</p></div>'


def steps(items):
    return '<div class="steps">' + ''.join(f'<div><span class="ordinal">{i:02}</span><h3>{title}</h3><p>{text}</p></div>' for i, (title, text) in enumerate(items, 1)) + '</div>'


def bars(items, limit=.25):
    out = '<div class="bar-chart" role="img" aria-label="LogLoss; меньше — лучше; шкала от нуля">'
    out += f'<div class="bar-axis"><span>0</span><span>{limit:.2f} · LogLoss ↓</span></div>'
    for label, value, color in items:
        width = value / limit * 100
        out += f'<div class="bar-row"><div class="bar-label">{esc(label)}</div><div class="bar-track"><span class="bar-fill {color}" style="width:{width:.5f}%"></span></div><span class="bar-value">{metric(value)}</span></div>'
    return out + '</div>'


